const o = load("open_result");
const project_ref = (o?.structuredContent ?? o).data.project_ref;
const args = {project_ref, execution_mode:"synchronous", timeout_seconds:60};
const results = {};
results.unsafe_scan = await tools.mcp__rust_engineering__rust_unsafe_scan(args);
results.supply_chain_inspect = await tools.mcp__rust_engineering__rust_supply_chain_inspect(args);
results.quality_gate_v2 = await tools.mcp__rust_engineering__rust_quality_gate_v2({...args, profile:"strict"});
results.miri = await tools.mcp__rust_engineering__rust_miri(args);
store("m4_retry_results", results);
function parse(r){
  if (r?.structuredContent) return r.structuredContent;
  const t=r?.content?.find(c=>c.type==="text")?.text;
  try{return JSON.parse(t)}catch{return {status:r?.isError?"tool_error":"unknown",error_message:t??null}}
}
for (const [k,r] of Object.entries(results)) {
  const x=parse(r);
  text(JSON.stringify({tool:k,status:x.status,error_code:x.error_code??null,error_message:x.error_message??null,summary:x.summary??null}));
}

const first=load("m4_results"), retry=load("m4_retry_results");
const all={project_open:load("open_result"),deny:first.deny,...retry};
function sc(r){
 if(r?.structuredContent)return r.structuredContent;
 const t=r?.content?.find(c=>c.type==="text")?.text;
 try{return JSON.parse(t)}catch{return {status:r?.isError?"tool_error":"unknown",error_message:t}}
}
function summarize(k,r){
 const x=sc(r), d=x.data||{}, rep=d.observation?.report||{};
 const z={tool:k,status:x.status,error_code:x.error_code??null,error_message:x.error_message??null,summary:x.summary??null};
 if(k==="project_open") Object.assign(z,{validation:d.validation,project_ref:d.project_ref});
 if(k==="deny") Object.assign(z,{completeness:d.completeness,policy_state:d.policy_state,audit_state:d.audit?.state,validation_complete:d.audit?.validation_complete,findings:d.findings?.length,findings_omitted:d.findings_omitted});
 if(k==="unsafe_scan") Object.assign(z,{syntax_complete:rep.syntax_complete,findings_total:rep.findings_total,findings_omitted:rep.findings_omitted,coverage:rep.coverage});
 if(k==="supply_chain_inspect") Object.assign(z,{complete:rep.complete,audit_availability:rep.audit_availability,audit_state:rep.audit?.state,deny_availability:rep.deny_availability,deny_policy_state:rep.deny?.policy_state,packages_total:rep.packages_total,packages_omitted:rep.packages_omitted});
 if(k==="quality_gate_v2") {
   z.profile=d.profile??d.observation?.profile??d.gate?.profile;
   z.verdict=d.verdict??d.observation?.verdict??d.gate?.verdict;
   z.complete=d.complete??d.observation?.complete??d.gate?.complete;
   z.stage_statuses=d.stages??d.observation?.stages??d.gate?.stages;
   z.data_keys=Object.keys(d);
 }
 if(k==="miri") Object.assign(z,{clean:rep.clean,complete:rep.complete,counts:rep.counts,findings_omitted:rep.findings_omitted});
 return z;
}
text(JSON.stringify(Object.fromEntries(Object.entries(all).map(([k,v])=>[k,summarize(k,v)])),null,2));

const r=load("m4_retry_results").quality_gate_v2;
const x=r.structuredContent ?? JSON.parse(r.content.find(c=>c.type==="text").text);
const o=x.data?.observation;
text(JSON.stringify({observation_keys:Object.keys(o||{}), observation:o},null,2).slice(0,20000));

